def _iter_applied_modifications(self) -> Iterator[TagBase]:
    """Iterate over each modification instance applied to the sequence."""
    last_position = len(self) - 1
    for i, (aa, tags) in enumerate(self.sequence):
        aa = aa.upper()
        for rule in self.fixed_modifications:
            if rule.is_valid(aa, i == 0, i == last_position):
                yield rule.modification_tag
        if tags:
            yield from tags
    yield from self.labile_modifications
    yield from self.unlocalized_modifications
    if self.n_term:
        yield from self.n_term
    if self.c_term:
        yield from self.c_term
    for interval in self.intervals:
        if interval.tags:
            yield from interval.tags

@property
def local_charge(self) -> int:
    """The total charge contributed by localized charged formulas."""
    charge = 0
    for tag in self._iter_applied_modifications():
        tag_charge = getattr(tag, 'charge', None)
        if tag_charge is not None:
            charge += tag_charge
    return charge

